        \If{\(t<T\) \textbf{and} \(\gamma_t^{i_t}>\delta_t\)}
        \State{maintain \(\ulcQ_{t+1}^{i_{t+1}+1}(x)\leftarrow\ulcQ_{t+1}^{i_{t+1}}(x),\;\olcQ_{t+1}^{i_{t+1}+1}(x)\leftarrow\olcQ_{t+1}^{i_{t+1}}(x)\)}
        \State{set \(t\leftarrow t+1\)}
        \Else
        \State{update \(\ulcQ_{t-1}^{i_{t-1}+1}(x)\leftarrow \max\{\ulcQ_{t-1}^{i_{t-1}}(x),\calV_{t-1}^{i_t}(x)\}\)}
        \State{update \(\olcQ_{t-1}^{i_{t-1}+1}(x)\leftarrow \conv\{\olcQ_{t-1}^{i_{t-1}}(x),v_{t-1}^{i_t}+M_{t-1}\Vert{x-x_{t-1}^{i_{t-1}}}\Vert\}\)}
        \State{set \(t\leftarrow t-1\)}
        \EndIf
        \EndIf
        \EndLoop
