\begin{align}\label{eq:DR-MSCP-Def}
    \min_{x_1\in\calX_1}\quad f_1(x_0,x_1;\xi_1)\ +&\sup_{p_2\in\calP_2}\bbE_{\xi_2\sim p_2} \min_{x_2\in\calX_2}\Bigg[f_2(x_1,x_2;\xi_2) + \\
    &+\sup_{p_3\in\calP_3}\bbE_{\xi_3\sim p_3} \min_{x_3\in\calX_3}\bigg[f_3(x_2,x_3;\xi_3)+\cdots\notag\\
    &+\sup_{p_T\in\calP_{T}}\bbE_{\xi_T\sim p_T} \min_{x_T\in\calX_T}f_T(x_{T-1},x_T;\xi_T)\bigg]\Bigg].\notag
\end{align}

Consequently, we can define the (worst-case expected) cost-to-go functions recursively from \(t=T\) to \(t=2\) as:
\begin{equation}\label{eq:DR-MSCP-Recursion}
    \calQ_{t-1}(x_{t-1})\coloneqq\sup_{p_t\in\calP_t}\bbE_{\xi_t\sim p_t}\min_{x_t\in\calX_t}f_t(x_{t-1},x_{t};\xi_{t})+\calQ_{t}(x_{t}),
\end{equation}

with \(\calQ_T(x_T)\equiv0\) for any \(x_T\in\calX_T\).
To simplify the notation, we also define 
\begin{equation}\label{eq:DR-MSCP-ValueFunction}
    Q_t(x_{t-1};\xi_t)\coloneqq\min_{x_t\in\calX_t}f_t(x_{t-1},x_t;\xi_t)+\calQ_t(x_t)
\end{equation}

Our algorithmic goal in this paper is to find a near-optimal first stage solution
\begin{equation}
    x_1^*\in\argmin_{x_1\in\calX_1} f_1(x_0,x_1;\xi_1)+\calQ_1(x_1),
\end{equation}

as a multistage solution may already take exponentially many operations in \(T\) to be written down, e.g., \(2^{T-1}\) if we have an MSCO with \(\abs{\Xi_t}=2\) for \(t=2,\dots,T\).
We say that \(x_1^*\) is an \(\epsilon\)-optimal first stage solution if 
\begin{equation}\label{eq:DR-MSCP-NearOptimalSolution}
    f_1(x_0,x_1^*;\xi_1)+Q_1(x_1^*)\le \varepsilon+\Big(\min_{x_1\in\calX_1}f_1(x_0,x_1;\xi_1)+\calQ_1(x_1)\Big).
\end{equation}

\begin{equation}\label{eq:RegularizedValueFunction}
    Q_t^\Reg(x_{t-1};\xi_t)\coloneqq\max_{\nVert{\lambda_t}_*\le M_t}\inf_{\substack{x_t\in\calX_t,\\z_t\in\bbR^{d_{t-1}}}}f_t(x_{t-1},x_t;\xi_t)+\calQ_t^\Reg(x_t)+\bangle{\lambda_t}{x_{t-1}-z_t},
\end{equation}

with \(\calQ_T^\Reg(x_T)\equiv0\) on \(\calX_T\) and
\begin{equation}\label{eq:RegularizedCostToGo}
    \calQ_{t-1}^\Reg(x_{t-1})\coloneqq\sup_{p_t\in\calP_t}\bbE_{\xi_t\sim p_t} Q_t^\Reg(x_{t-1};\xi_t)
\end{equation}

\begin{definition}[Initial stage subproblem oracle]
    \label{def:InitialStageOracle}
    Let \(\ulcQ_1,\olcQ_1:\calX_1\to\bbR\cup\{+\infty\}\) denote two lsc, convex functions, with \(\ulcQ_1(x_1)\le\calQ_1^\Reg(x_1)\le\olcQ_1(x_1)\) for any \(x_1\in\calX_1\).
    Consider the following subproblem for the first stage \(t=1\),
    \begin{equation}\label{eq:InitialStageOracle}
        \min_{x_1\in\calX_1}f_1(x_0,x_1;\xi_1)+\ulcQ_1(x_1).\tag{I}
    \end{equation}
    The initial stage subproblem oracle provides an optimal solution \(x_1\) to~\eqref{eq:InitialStageOracle} and calculates the approximation gap \(\gamma_1\coloneqq\olcQ_1(x_1)-\ulcQ_1(x_1)\).
    We thus define the subproblem oracle formally as a map \(\scrO_1:(\ulcQ_1,\olcQ_1)\mapsto(x_1;\gamma_1)\).
\end{definition}

\begin{definition}[Noninitial stage subproblem oracle]
    \label{def:NoninitialStageOracle}
    For any \(t\in\calT'\), let \(\ulcQ_t,\olcQ_t:\calX_t\to\bbR\cup\{+\infty\}\) denote two lsc, convex functions, with \(\ulcQ_t(x_t)\le\calQ_t^\Reg(x_t)\le\olcQ_t(x_t)\) for all \(x_t\in\calX_t\).
    Then given a feasible state \(x_{t-1}\in\calX_{t-1}\), the stage-\(t\) subproblem oracle provides a feasible state \(x_t\in\calX_t\), an \(M_t\)-Lipschitz continuous linear cut \(\calV_{t-1}(\,\cdot\,)\), and an over-estimate value \(v_{t-1}\) such that
    \begin{compactitem}
        \item they are valid, i.e., \(\calV_{t-1}(\cdot)\le\calQ_{t-1}^\Reg(\cdot)\) on \(\calX_{t-1}\) and \(v_{t-1}\ge\calQ_{t-1}^\Reg(x_{t-1})\);
        \item the gap is controlled, i.e., \(v_{t-1}-\calV_{t-1}(x_{t-1})\le\gamma_t\coloneqq\olcQ_t(x_t)-\ulcQ_t(x_t)\).
    \end{compactitem}
    We thus define the subproblem oracle formally as a map \(\scrO_t:(x_{t-1},\ulcQ_t,\olcQ_t)\mapsto(\calV_{t-1},v_{t-1},x_t;\gamma_t)\).
\end{definition}

\begin{algorithm}[ht]
    \caption{Consecutive Dual Dynamic Programming Algorithm}
    \label{alg:ConsecutiveDualDP}
    \begin{algorithmic}[1]
        \Require{subproblem oracles \(\scrO_t\) for \(t\in\calT\), target optimality gap \(\epsilon>0\)} 
        \Ensure{an \(\epsilon\)-optimal first stage solution \(x_1^*\)}
        \State{initialize: \(\ulcQ_t^0\leftarrow 0,\olcQ_t^0\leftarrow +\infty,t\in\calT\backslash\{T\}\); \(\ulcQ_T^j,\olcQ_T^j\leftarrow0,j\in\bbN\); \(i\leftarrow 1\)}
        \State{evaluate \((x_1^1;\gamma_1^1)\leftarrow\scrO_1(\ulcQ_1^0,\olcQ_1^0)\)}
        \State{set \(\LB\leftarrow f_1(x_0,x_1^1;\xi_1),\ \UB\leftarrow +\infty\)}
        \While{\(\UB-\LB >\epsilon\)}
        \For{\(t=2,\dots,T\)}
        \State{evaluate \((\calV_{t-1}^{i},v_{t-1}^{i},x_t^i;\gamma_t^i)=\scrO_t(x_{t-1}^i,\ulcQ_t^{i-1},\olcQ_t^{i-1})\)}
        \Comment{forward step}
        \EndFor
        \For{\(t=T,\dots,2\)}
        \State{update \(\ulcQ_{t-1}^i(x)\leftarrow \max\{\ulcQ_{t-1}^{i-1}(x),\calV_{t-1}^i(x)\}\)}
        \Comment{backward step}
        \State{update \(\olcQ_{t-1}^i(x)\leftarrow \conv\{\olcQ_{t-1}^{i-1}(x),v_{t-1}^i+M_{t}\nVert{x-x_{t-1}^i}\}\)}
        \EndFor
        \State{evaluate \((x_1^{i+1};\gamma_1^{i+1})\leftarrow\scrO_1(\ulcQ_1^i,\olcQ_1^i)\)}
        \Comment{initial stage step}
        \State{update \(\LB\leftarrow f_1(x_0,x_1^{i+1};\xi_1)+\ulcQ_1^i(x_1^{i+1})\)}
        \State{update \(\UB'\leftarrow f_1(x_0,x_1^{i+1};\xi_1)+\olcQ_1^i(x_1^{i+1})\)}
        \If{\(\UB'<\UB\)}
        \State{set \(x_1^*\leftarrow x_1^{i+1}\),  \(\UB\leftarrow\UB'\)}
        \EndIf
        \State{update \(i\leftarrow i+1\)}
        \EndWhile
    \end{algorithmic}
\end{algorithm}

\begin{algorithm}[ht]
    \caption{Nonconsecutive Dual Dynamic Programming (NDDP) Algorithm}
    \label{alg:NonconsecutiveDualDP}
    \begin{algorithmic}[1]
        \Require{subproblem oracles \(\scrO_t\) for \(t\in\calT\), opt.\ and approx.\ gaps \(\epsilon=\delta_1>\cdots>\delta_T=0\)} 
        \Ensure{an \(\epsilon\)-optimal first stage solution \(x_1^*\)}
