        \Comment{initial stage step}
        \State{update \(\LB\leftarrow f_1(x_0,x_1^{i_1};\xi_1)+\ulcQ_1^{i_1}(x_1^{i_1})\)}
        \State{update \(\UB'\leftarrow f_1(x_0,x_1^{i_1};\xi_1)+\olcQ_1^{i_1}(x_1^{i_1})\)}
