        \If{\(\UB-\LB\le\epsilon\)}
        \State{\bfseries{break the loop}}
        \EndIf
        \State{maintain \(\ulcQ_2^{i_2+1}(x)\leftarrow\ulcQ_2^{i_2}(x),\;\olcQ_2^{i_2+1}(x)\leftarrow\olcQ_2^{i_2}(x)\)}
        \State{set \(t\leftarrow t+1\)}
        \Else
        \State{evaluate \((\calV_{t-1}^{i_t},v_{t-1}^{i_t},x_t^{i_t};\gamma_t^{i_t})\leftarrow\scrO_t(x_{t-1}^{i_{t-1}},\ulcQ_t^{i_t},\olcQ_t^{i_t})\)}
        \Comment{noninitial stage step}
        \If{\(t<T\) \textbf{and} \(\gamma_t^{i_t}>\delta_t\)}
        \State{maintain \(\ulcQ_{t+1}^{i_{t+1}+1}(x)\leftarrow\ulcQ_{t+1}^{i_{t+1}}(x),\;\olcQ_{t+1}^{i_{t+1}+1}(x)\leftarrow\olcQ_{t+1}^{i_{t+1}}(x)\)}
        \State{set \(t\leftarrow t+1\)}
