    For stage any \(t<T\), suppose the state space \(\calX_t\subset\bbR^{d_t}\) is contained in a ball with diameter \(D_t>0\).
    Then,
    \begin{equation}\label{eq:FiniteIndexSet}
        \abs{\calI_t(\delta)}\le\left(1+\frac{2M_{t+1} D_t}{\delta_t-\delta_{t+1}}\right)^{d_t}.
    \end{equation}
\end{lemma}

\begin{proof}
    We claim that for any \(j,k\in\calI_t\), \(j\neq k\), it holds that \(\nVert{x_t^j-x_t^k}>(\delta_t-\delta_{t+1})/(2M_{t+1})\).
    Assume for contradiction that \(\nVert{x_t^j-x_t^k}\le(\delta_t-\delta_{t+1})/(2M_{t+1})\) for some \(j<k\), \(j,k\in\calI_t(\delta)\).
    By definition of \(\calI_t(\delta)\), the \((t+1)\)-th subproblem oracle is evaluated at the state \(x_t^j\), and in both the CDDP and the NDDP algorithms, the approximations \(\ulcQ_t^j\) and \(\olcQ_t^j\) are updated since \(\gamma_{t+1}^{i_{t+1}}\le\delta_{t+1}\) for some \(i_{t+1}\in\bbN\) with \((j,i_{t+1})\in\calJ_{t+1}\).
    Then by Definition~\ref{def:NoninitialStageOracle} of the noninitial stage subproblem oracle, we have \(\olcQ_t^{j+1}(x_t^j)-\ulcQ_t^{j+1}(x_t^j)\le \delta_{t+1}\).
    Note that for any point \(x\in\calX_t\) with \(\nVert{x-x_t^j}\le(\delta_t-\delta_{t+1})/(2M_{t+1})\), we have \(\olcQ_t^{j+1}(x)-\ulcQ_t^{j+1}(x)\le \delta_{t}\) because of the \(M_{t+1}\)-Lipschitz continuity of the approximations.
    Since \(\olcQ_t^{k}(x)\le\olcQ_t^{j+1}(x)\) and \(\ulcQ_t^{k}(x)\ge\ulcQ_t^{j+1}(x)\), by setting \(x=x_t^k\), we see a contradiction with the assumption that \(k\in\calI_t(\delta)\), which proves the claim.

    To ease the notation, let \(r_t\coloneqq(\delta_t-\delta_{t+1})/(2M_{t+1})\) denote the radius of the \(d_t\)-dimensional balls \(\calB^{d_t}(x_t^j;r_t)\) centered at \(x_t^j\) for \(j\in\calI_t(\delta)\), and let \(\calB_t\supseteq\calX_t\) denote a ball with diameter \(D_t\).
    From the above claim, we know that \(x_t^k\notin\calB^{d_t}(x_t^j;r_t)\) for any \(j,k\in\calI_t(\delta)\) with \(j<k\).
    In other words, the smaller balls \(\calB^{d_t}(x_t^j;r_t/2)\) are disjoint.
    Meanwhile, note that each of these smaller balls satisfies \(\calB^{d_t}(x_t^j;r_t/2)\subset\calB_t+\calB^{d_t}(0;r_t/2)\) (the Minkowski sum in the Euclidean space \(\bbR^{d_t}\)).
    Therefore, the volumes satisfy the relation
    \begin{equation*}
     \Vol\left(\textstyle\bigcup_{j\in\calI_t(\delta)}\calB^{d_t}(x_t^j;r_t/2)\right)
        =\abs{\calI_t(\delta)}\cdot\Vol\calB^{d_t}(0;r_t/2)
        \le\Vol\left(\calB_t+\calB^{d_t}(0;r_t/2)\right),
    \end{equation*}
    which implies that
    \begin{equation*}
        \abs{\calI_t(\delta)}\le\frac{\Vol(\calB_t+\calB^{d_t}(0;r_t/2))}{\Vol\calB^{d_t}(0;r_t/2)}
        =\left(\frac{D_t/2+r_t/2}{r_t/2}\right)^{d_t}
        =\left(1+\frac{2M_{t+1}D_t}{\delta_t-\delta_{t+1}}\right)^{d_t}.
    \end{equation*}
\end{proof}

Therefore, the volumes satisfy the relation
\begin{equation*}
 \Vol\left(\textstyle\bigcup_{j\in\calI_t(\delta)}\calB^{d_t}(x_t^j;r_t/2)\right)
    =\abs{\calI_t(\delta)}\cdot\Vol\calB^{d_t}(0;r_t/2)
    \le\Vol\left(\calB_t+\calB^{d_t}(0;r_t/2)\right),
\end{equation*}

which implies that
\begin{equation*}
    \abs{\calI_t(\delta)}\le\frac{\Vol(\calB_t+\calB^{d_t}(0;r_t/2))}{\Vol\calB^{d_t}(0;r_t/2)}
    =\left(\frac{D_t/2+r_t/2}{r_t/2}\right)^{d_t}
    =\left(1+\frac{2M_{t+1}D_t}{\delta_t-\delta_{t+1}}\right)^{d_t}.
\end{equation*}

\begin{theorem}\label{thm:NDDPComplexityBound}
    Suppose the state spaces \(\calX_t\subset\bbR^{d_t}\) are contained in balls, each with diameter \(D_t>0\).
    Then, for the NDDP algorithm (Algorithm~\ref{alg:NonconsecutiveDualDP}) with the predetermined approximation gap vector \((\delta_t)_{t=1}^{T}\) satisfying \(\epsilon=\delta_1>\delta_2>\cdots>\delta_T=0\), 
    the total number of subproblem oracle evaluations \(\NumEval_\NDDP\) before termination is bounded by
    \begin{equation*}
        \NumEval_\NDDP\le 1+2\cdot\sum_{t=1}^{T-1}\left(1+\frac{2M_{t+1}D_t}{\delta_t-\delta_{t+1}}\right)^{d_t}.
    \end{equation*}
\end{theorem}

\begin{proof}
    For the NDDP algorithm, each time when it decides to go back to the precedent stage \(t\leftarrow t-1\), we must have \(\gamma_t^{i_t}\le\delta_t\) while \(\gamma_{t-1}^{i_{t-1}}>\delta_{t-1}\) for some \((i_{t-1},i_t)\in\calJ_t\).
    In this case, we have by definition that \(i_{t-1}\in\calI_{t-1}(\delta)\).
    By Lemma~\ref{lemma:FiniteIndexSet}, such ``going back'' steps can only happen at most \(\sum_{t=1}^{T-1}\abs{\calI_t(\delta)}\) times.
    The total number of evaluations is then bounded by two times the number of ``going back'' steps due to the corresponding ``going forward'' steps, plus an additional evaluation of the initial stage oracle for checking the termination criterion.
\end{proof}
